import sharp from "sharp";
import { mkdir, readFile, writeFile } from "node:fs/promises";
await mkdir("public/icons", { recursive: true });
// Generated by docs/brand/make_logo.py; the art already sits inside the maskable safe zone.
const svg = await readFile("docs/brand/manin-icone.svg");
for (const [file, size] of [
  ["icon-192", 192],
  ["icon-512", 512],
  ["maskable-512", 512],
  ["apple-touch-icon", 180],
])
  await sharp(svg, { density: 300 })
    .resize(size, size)
    .png()
    .toFile(`public/icons/${file}.png`);
// PNG favicons for browsers that skip the SVG one (Safari history, older engines).
const symbol = await readFile("docs/brand/manin-simbolo.svg");
const favicon = (size) =>
  sharp(symbol, { density: 300 })
    .resize(size, size, {
      fit: "contain",
      background: { r: 0, g: 0, b: 0, alpha: 0 },
    })
    .png()
    .toBuffer();
await writeFile("public/icons/favicon-96.png", await favicon(96));
// favicon.ico = one 32px PNG inside an ICO header (ICONDIR + ICONDIRENTRY).
const png = await favicon(32);
const ico = Buffer.alloc(22);
ico.writeUInt16LE(1, 2); // type: icon
ico.writeUInt16LE(1, 4); // one image
ico.writeUInt8(32, 6); // width
ico.writeUInt8(32, 7); // height
ico.writeUInt16LE(1, 10); // colour planes
ico.writeUInt16LE(32, 12); // bits per pixel
ico.writeUInt32LE(png.length, 14);
ico.writeUInt32LE(22, 18); // image data offset
await writeFile("public/favicon.ico", Buffer.concat([ico, png]));
